insert into question_bank_items (id, stage_id, position, question, hint, answer) values (90, 6, 14, 'איפה אתה רואה את עצמך בעוד חמש שנים?', 'כיוון שסביר עובר דרך התפקיד הזה, לא תואר-פנטזיה.', ARRAY['בחרו מסלול אמין — שליטה טכנית עמוקה יותר, בעלות על אסטרטגיית בדיקות, מסלול SDET או ליד — וקשרו למיומנויות שתבנו בעבודה הזו.', 'סמנו מחויבות בלי להבטיח יתר. "אני רוצה להחזיק את האיכות של תחום מוצר ולחנוך אחרים" מרגיע אותם שאינכם מתייחסים לתפקיד כתחנת מעבר של חודשיים.', 'שמרו על כנות וגמישות: התחום זז מהר, אז מסגרו זאת ככיוון שאתם חותרים אליו ולא כיעד קבוע.']::text[]);
insert into question_bank_stages (id, lang, position, icon, title) values (7, 'he', 1, '🎭', 'שלב 2 — ידע באוטומציית בדיקות');
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (91, 7, 0, 'מהו Page Object Model ואיזו בעיה הוא פותר?', 'הגדירו קודם את הבעיה — הסלקטור שמופיע בארבעים ספקים.', ARRAY['Page object עוטף מסך מאחורי API שמבטא כוונה: `loginPage.signIn(user, pass)` במקום שרשרת סלקטורים ולחיצות בתוך הבדיקה.', 'הבעיה שהוא פותר היא שכפול *ידע*. כשה-data-testid משתנה, משתנה מחלקה אחת — ולא כל ספק שאי פעם נגע בשדה הזה.', 'השאירו assertions מחוץ ל-page object. האובייקט חושף מצב ופעולות; הבדיקה מחליטה מה נכון. ערבוב גורם לכשלים לדווח על השכבה הלא נכונה וחוסם שימוש חוזר.', 'מדלו רכיבים חוזרים — ניווט, מודאל, טבלה — כ-component objects במקום להעתיק אותם לכל מחלקת עמוד, ותנו לעמוד להרכיב אותם.', 'הכירו גם את הביקורת: בפרונט מבוסס רכיבים, page objects עלולים להיות ברזולוציה הלא נכונה, ולעיתים component objects עם לוקייטורים לפי role משרתים טוב יותר.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (92, 7, 1, 'איך אתה מחליט מה לאוטמט ומה להשאיר כבדיקה ידנית?', 'ערך ≈ סיכון × תדירות ÷ עלות בנייה ותחזוקה.', ARRAY['אוטמו את מה שחוזר על עצמו, דטרמיניסטי וקריטי לעסק: מסלולי smoke, רגרסיה סביב כסף והרשאות, חוזי API, וכל מה שאחרת תריצו בכל גרסה.', 'השאירו ידני: בדיקות חוקרות, שיפוט ויזואלי ושימושיות, מיגרציות חד-פעמיות, ואזורים שמשתנים שבועית — הבדיקה תיכתב מחדש לפני שתחזיר את עלותה.', 'שקללו תחזוקה ולא רק כתיבה. בדיקה שעולה שעה בשבוע כדי להישאר ירוקה חייבת לחסוך יותר משעה בשבוע.', 'אמרו במפורש ש-100% אוטומציה אינה המטרה. כיסוי *סיכון* הוא המטרה, ואלה לא אותו מספר.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (93, 7, 2, 'בדיקה עוברת מקומית אך מתנדנדת (flaky) ב-CI. איך תאבחן ותתקן?', 'קודם הוכיחו שזו הבדיקה ולא המוצר — ואז אתרו איזו מארבע הסיבות הרגילות זו.', ARRAY['שללו קודם באג אמיתי לסירוגין. בדיקה מתנדנדת לפעמים מעידה על race אמיתי במוצר, ו"ייצוב" הבדיקה פשוט יסתיר תקלה.', 'שחזרו במכוון: הריצו בלולאה, ובתנאים דמויי CI — עובדים במקביל, מכונה איטית יותר, cache קר, אזור זמן ושפה אחרים.', 'מיינו לפי סיבה: תזמון (sleep, אנימציות, בקשות שלא המתינו להן), מצב משותף (תלות בסדר, נתונים שנשארו), סביבה (שעון, רשת, מגבלות משאבים) ונתונים לא דטרמיניסטיים (ערכים אקראיים, תאריך היום).', 'תקנו בהמתנה לתנאי במקום למשך זמן, בכך שכל בדיקה תזרע ותנקה את הנתונים של עצמה, ובקיבוע זמן ואקראיות. הכניסו ל-quarantine בקול וברור עם תאריך יעד — לעולם לא retry-until-green בשקט.', 'עקבו אחרי שיעור flaky כמדד ממדרגה ראשונה. בלעדיו, תיקיית ה-quarantine הופכת לבית קברות.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (94, 7, 3, 'המתנות מפורשות מול משתמעות — מתי כל אחת, ולמה להימנע מ-sleep קבוע?', 'אחת ממתינה לתנאי, אחת היא ברירת מחדל גלובלית, ואחת היא הימור נגד המכונה.', ARRAY['המתנה מפורשת חוסמת עד שתנאי מסוים מתקיים — אלמנט גלוי, בקשה הסתיימה, טקסט תואם — עם timeout. היא מדויקת ומתעדת את עצמה.', 'המתנה משתמעת היא ברירת מחדל גלובלית לכל חיפוש אלמנט. היא מסתירה כוונה, וערבוב שלה עם המתנות מפורשות עלול לצבור timeouts בדרכים שקשה מאוד לנפות.', '`sleep(3)` הוא הימור שהמכונה לעולם לא איטית מהלפטופ שלכם ולעולם לא מהירה מהסבלנות שלכם. הוא גם מתנדנד וגם איטי — הרע שבשני העולמות.', 'פריימוורקים מודרניים ממתינים אוטומטית ל-actionability, כך שמה שנשאר הוא המתנה למצב *האפליקציה*: תגובת רשת שהתייצבה, ספינר שנעלם, מספר שורות שהושג.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (95, 7, 4, 'איך אתה שומר על בדיקות מבודדות ובלתי תלויות בסדר ההרצה?', 'כל בדיקה יוצרת את מה שהיא צריכה ולא משאירה כלום.', ARRAY['כל בדיקה מקימה את הנתונים שלה — דרך API או fixture, לא דרך ה-UI — עם מזהים ייחודיים כדי שהרצות מקבילות לא יתנגשו על אותה רשומה.', 'נקו ב-teardown ללא תלות בתוצאה, או השתמשו בסביבות חד-פעמיות/טרנזקציוניות כך שהניקוי חינמי ואי אפשר לשכוח אותו.', 'לעולם אל תסתמכו על תופעות לוואי של בדיקה קודמת. אם B צריכה את המצב של A, אחדו אותן לבדיקה אחת או תנו ל-B setup משלה.', 'הוכיחו במקום להניח: הריצו את הסוויטה בסדר אקראי ובמקביל ב-CI. תלות בסדר שלא נבדקת היא פשוט כשל שטרם פגשתם.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (96, 7, 5, 'איך היית בונה סוויטה על פני שכבות UI, API ו-unit (פירמידת הבדיקות)?', 'העלות ומהירות המשוב בכל שכבה קובעות את הצורה.', ARRAY['הרבה בדיקות יחידה (מהירות, מדויקות, רצות בכל שמירה), פחות בדיקות שירות/API וחוזה, והכי מעט מסעות end-to-end.', 'ההיגיון כלכלי: בדיקת UI איטית, תלוית סביבה ומעורפלת לגבי הסיבה; בדיקת יחידה מיידית ומצביעה על פונקציה.', 'שמרו E2E למסעות משתמש קריטיים — התחברות, רכישה, מסלול הכסף — ולא לכל פרמוטציה, ששייכת לשכבה נמוכה וזולה יותר.', 'נקבו באנטי-דפוס: גביע הגלידה, שבו צוות מדלג על האמצע ותולה הכול בבדיקות UI. בדיקות API וחוזה הן בדרך כלל המקום שבו נמצא המנוף האמיתי.']::text[]);